package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_Integer() {
        Number res = NumberUtils.createNumber("123");
        assertTrue(res instanceof Integer);
        assertEquals(123, ((Integer) res).intValue());
    }

    @Test
    public void testCreateNumber_Long() {
        Number res = NumberUtils.createNumber("1234567890123");
        assertTrue(res instanceof Long);
        assertEquals(1234567890123L, ((Long) res).longValue());
    }

    @Test
    public void testCreateNumber_BigInteger() {
        String bigVal = "123456789012345678901234567890";
        Number res = NumberUtils.createNumber(bigVal);
        assertTrue(res instanceof BigInteger);
        assertEquals(new BigInteger(bigVal), (BigInteger) res);
    }

    @Test
    public void testCreateNumber_Float() {
        // numDecimals <= 7
        Number res = NumberUtils.createNumber("1.2345");
        assertTrue(res instanceof Float);
        assertEquals(1.2345f, ((Float) res).floatValue(), 1e-6);
    }

    @Test
    public void testCreateNumber_Double() {
        // numDecimals between 8 and 16
        Number res = NumberUtils.createNumber("1.123456789012");
        assertTrue(res instanceof Double);
        assertEquals(1.123456789012, ((Double) res).doubleValue(), 1e-12);
    }

    @Test
    public void testCreateNumber_BigDecimal() {
        // numDecimals > 16
        Number res = NumberUtils.createNumber("1.1234567890123456789");
        assertTrue(res instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_WithExponent() {
        // 1.2e3 -> mantissa 1.2, exp 3. dec=1, exp=1. 
        // Decimals <= 7, so Float
        Number res = NumberUtils.createNumber("1.2e3");
        assertTrue(res instanceof Float);
        assertEquals(1200.0f, ((Float) res).floatValue(), 1e-2);
    }

    @Test
    public void testCreateNumber_SuffixL() {
        Number res = NumberUtils.createNumber("123L");
        assertTrue(res instanceof Long);
        assertEquals(123L, ((Long) res).longValue());

        Number bigL = NumberUtils.createNumber("12345678901234567890L");
        assertTrue(bigL instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_SuffixF() {
        Number res = NumberUtils.createNumber("123.45f");
        assertTrue(res instanceof Float);
        assertEquals(123.45f, ((Float) res).floatValue(), 1e-2);
    }

    @Test
    public void testCreateNumber_SuffixD() {
        Number res = NumberUtils.createNumber("123.45d");
        assertTrue(res instanceof Double);
        assertEquals(123.45, ((Double) res).doubleValue(), 1e-2);
    }

    @Test
    public void testCreateNumber_InvalidSuffix() {
        try {
            NumberUtils.createNumber("123z");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            assertTrue(e.getMessage().contains("is not a valid number"));
        }
    }

    @Test
    public void testCreateNumber_AllZerosLogic() {
        // Test the allZeros logic for Float/Double fallback
        // If it's 0.000000000001 (too small for float) but not "all zeros"
        Number res = NumberUtils.createNumber("0.00000000000000000001");
        assertTrue(res instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_ExponentError() {
        // Case where expPos < decPos
        try {
            NumberUtils.createNumber("1e2.3");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
        }
    }

    @Test
    public void testCreateNumber_DoubleExponentError() {
         // Case where expPos > str.length() is handled by logic
         // We target the exception: if (expPos < decPos || expPos > str.length())
         // This can be triggered by malformed strings like "1.2e" if logic allows
         // However, the code checks expPos > -1 && expPos < str.length() - 1
    }

    @Test
    public void testCreateNumber_LargeFloatFallback() {
        // A number that is too big for Float but valid for Double
        // 1e38 is roughly max float
        Number res = NumberUtils.createNumber("1e38");
        assertTrue(res instanceof Float);

        Number resBig = NumberUtils.createNumber("1e40");
        assertTrue(resBig instanceof Double);
    }

    @Test
    public void testCreateNumber_NegativeNumbers() {
        Number res = NumberUtils.createNumber("-123");
        assertEquals(-123, ((Integer) res).intValue());

        Number resNegL = NumberUtils.createNumber("-123L");
        assertEquals(-123L, ((Long) resL).longValue());
    }

    @Test
    public void testCreateNumber_DecimalOnly() {
        Number res = NumberUtils.createNumber("123.");
        // Last char is '.', so it goes to the "no decimal point and no exponent" block logic or similar
        // Actually, if lastChar == '.', it falls through to the bottom section
        assertTrue(res instanceof Float || res instanceof Double || res instanceof BigDecimal);
    }
}
